/**
 * App install icons, embedded as base64 text.
 *
 * Why: the flagship repo is pushed through a text-only pipeline (the
 * GitHub connector stores file content as text), so binary PNGs cannot
 * live in the repo as real PNG files — earlier attempts stored the
 * base64 text itself at the .png paths, which browsers cannot render
 * as images. The API therefore serves the decoded bytes at
 * GET /api/v1/app/icons/<name>.png (routes/app.js), and the PWA
 * manifests + apple-touch-icon links point there.
 */
export const PLUG_192 = '';

export const PLUG_512 = '';

export const PRO_192 = '';

export const PRO_512 = '';

